package com.spawnershop.gui;
import com.spawnershop.SpawnerShopPlugin; import com.spawnershop.api.SpawnerShopCloseEvent; import com.spawnershop.config.*; import com.spawnershop.service.TransactionService; import org.bukkit.Bukkit; import org.bukkit.entity.Player; import org.bukkit.event.EventHandler; import org.bukkit.event.Listener; import org.bukkit.event.inventory.InventoryClickEvent; import org.bukkit.event.inventory.InventoryCloseEvent; import org.bukkit.event.inventory.InventoryDragEvent;
public final class ShopListener implements Listener { private final SpawnerShopPlugin plugin;private final ShopView view;private final ShopRepository shops;private final TransactionService transactions; public ShopListener(SpawnerShopPlugin p,ShopView v,ShopRepository s,TransactionService t){plugin=p;view=v;shops=s;transactions=t;}
 @EventHandler public void click(InventoryClickEvent e){if(!(e.getInventory().getHolder() instanceof ShopHolder))return;e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player p)||e.getRawSlot()<0||e.getRawSlot()>=e.getInventory().getSize())return;int sell=plugin.getConfig().getInt("shop.sell-all.slot",48);if(e.getRawSlot()==sell){int n=transactions.sellAll(p,shops.all());p.sendMessage(org.bukkit.ChatColor.GREEN+"Sold "+n+" items.");return;}shops.itemAt(e.getRawSlot()).ifPresent(item->{int amount=e.isShiftClick()?64:1;switch(e.getClick()){case LEFT, SHIFT_LEFT -> transactions.buy(p,item,amount);case RIGHT, SHIFT_RIGHT -> transactions.sell(p,item,amount);default -> {}}});}
 @EventHandler public void drag(InventoryDragEvent e){if(e.getInventory().getHolder() instanceof ShopHolder)e.setCancelled(true);}
 @EventHandler public void close(InventoryCloseEvent e){if(e.getInventory().getHolder() instanceof ShopHolder && e.getPlayer() instanceof Player p) Bukkit.getPluginManager().callEvent(new SpawnerShopCloseEvent(p));}
}
